	//SENTRY LINK TEST CASES
	public void AX_SENTRYLINK_LockUserUnlockUsingSentryLink()
	{
		CommonWeb clsCommonWeb = new CommonWeb();
		String strBrowser = objDictionary.get("strBrowser");
		String strRemotePath = objDictionary.get("strRemotePath");
		String strRole = "parker";
		String strErrorMsg = "";
		//Open SentryLink
		threadDriver =clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
		WebDriver driver = getDriver();
		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_LoginInOrCreate(objDictionary, driver, strRole);
		String strActualWaitValue = clsCommonWeb.strActualWaitValue;
		if(strActualWaitValue.equals("SignInSuccessfully"))
  	 	{
			driver.quit();
			//Lock Account
			threadDriver =clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
			clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
			String strUniqueId = objDictionary.get("strUniqueId");
			String strMunicipality = objDictionary.get("strMunicipality");
	  		String strUserName = strUniqueId+strMunicipality.replace(" ","").replace(",", "")+strRole.replace(" ","")+"@mpspark.com";
			String strIncorrectPassword = strUniqueId+strMunicipality.replace(", ", "").replace(" ", "")+strRole.replace(" ","");
			//Login #1
			clsCommonWeb.PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password", strUserName+"|"+strIncorrectPassword);
			clsCommonWeb.ClickButton(objDictionary, driver, "Login", "Sign in",1,"Local");
			strActualWaitValue = clsCommonWeb.strActualWaitValue;
			if(!strActualWaitValue.equals("InvalidEmailOrPassword")){Reporter.log("<font color='red'>The message Invalid Email Or Password did not appear</font>");Assert.fail(strErrorMsg);}
			Reporter.log("Invalid Email Or Password message appeared successfully");
			//Login #2
			clsCommonWeb.PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password", strUserName+"|"+strIncorrectPassword);
			clsCommonWeb.ClickButton(objDictionary, driver, "Login", "Sign in",1,"Local");
			strActualWaitValue = clsCommonWeb.strActualWaitValue;
			if(!strActualWaitValue.equals("InvalidEmailOrPassword")){Reporter.log("<font color='red'>The message Invalid Email Or Password did not appear</font>");Assert.fail(strErrorMsg);}
			Reporter.log("Invalid Email Or Password message appeared successfully");
			//Login #3
			clsCommonWeb.PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password", strUserName+"|"+strIncorrectPassword);
			clsCommonWeb.ClickButton(objDictionary, driver, "Login", "Sign in",1,"Local");
			strActualWaitValue = clsCommonWeb.strActualWaitValue;
			if(!strActualWaitValue.equals("InvalidEmailOrPassword")){Reporter.log("<font color='red'>The message Invalid Email Or Password did not appear</font>");Assert.fail(strErrorMsg);}
			Reporter.log("Invalid Email Or Password message appeared successfully");
			//Login #4
			clsCommonWeb.PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password", strUserName+"|"+strIncorrectPassword);
			clsCommonWeb.ClickButton(objDictionary, driver, "Login", "Sign in",1,"Local");
			strActualWaitValue = clsCommonWeb.strActualWaitValue;
			if(!strActualWaitValue.equals("YouHaveOneMoreAttemptBeforeYourAccountIsLocked")){Reporter.log("<font color='red'>The message You Have One More Attempt Before Your Account Is Locked message did not appear</font>");Assert.fail(strErrorMsg);}
			Reporter.log("You Have One More Attempt Before Your Account Is Locked message appeared successfully");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password", strUserName+"|"+strIncorrectPassword);
			clsCommonWeb.ClickButton(objDictionary, driver, "Login", "Sign in",1,"Local");
			strActualWaitValue = clsCommonWeb.strActualWaitValue;
			if(!strActualWaitValue.equals("YourAccountIsLocked")){Reporter.log("<font color='red'>The message Your Account Is Locked message did not appear</font>");Assert.fail(strErrorMsg);}
			Reporter.log("Your Account Is Locked message appeared successfully");
			driver.quit();
			threadDriver =clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
			clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary,  driver);
			String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Approved Users","Local");
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Parker Users", 1);
			clsCommonWeb.SENTRYLINK_SearchUserByOnApprovedUserPage(objDictionary, driver, "parker");
			clsCommonWeb.ClickTableLinkByColumnValue(objDictionary, driver, "Approved Users", "Users", 1, 2, strUserName, "Unlock");
			clsCommonWeb.VerificationPointText(objDictionary, driver, "Approved Users", "UserWasSuccessfullyUpdated", 1, "Contains", "User was successfully updated.");
			getDriver().close();
  	 	}
    }

